// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address currentOwner, address actor, address newOwner) public {
        vm.assume(currentOwner != address(0));
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));

        address priorOwner = c.owner();

        vm.prank(actor);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        if (actor != priorOwner) {
            assertTrue(c.owner() == priorOwner);
        } else {
            assertTrue(c.owner() == priorOwner || c.owner() == newOwner);
        }
    }
}
